input.sparql:
SELECT ?z ?label ?pt ?pclass ?tsid WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?label .
  ?z brick:hasPoint ?pt .
  ?pt ref:hasTimeseriesId ?tsid .
}

